<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { app, game, gs, setMode, stepLevel, interact, setEditing, toggleTorch, cancelJoin, leave, undoEdit, redoEdit, act, open, aimAt, possess, active, setGrid, newHero, peek, aimToken } from '../session'
import { mine } from '../heroes'
import type { Mode } from '../engine/view'
import { monster } from '../rules/monsters'
import { rich } from './rich'
import Portrait from './Portrait.vue'
import Icon from './Icon.vue'
import EditBar from './EditBar.vue'
import Tags from './Tags.vue'
import DiceRoll from './DiceRoll.vue'
import Feed from './Feed.vue'
import Hotbar from './Hotbar.vue'
import Ribbon from './Ribbon.vue'
import Party from './Party.vue'
import DmDock from './DmDock.vue'
import Minimap from './Minimap.vue'
import Palette from './Palette.vue'
import Bits from './Bits.vue'
import HeroSheet from './HeroSheet.vue'
import LevelUp from './LevelUp.vue'
import Settings from './Settings.vue'
import RollCall from './RollCall.vue'
import SceneCard from './SceneCard.vue'
import TalkCard from './TalkCard.vue'
import Amend from './Amend.vue'
const modes: { m: Mode; n: string; t: string; k: string }[] = [{ m: 'fps', n: 'First', t: 'First person', k: '1' }, { m: 'tps', n: 'Third', t: 'Third person', k: '2' }, { m: 'iso', n: 'Tilt', t: 'Isometric', k: '3' }, { m: 'top', n: 'Map', t: 'Top down', k: '4' }, { m: 'fly', n: 'Fly', t: 'Fly', k: '5' }]; const cycle = () => { const L = shown.value, i = L.findIndex(m => m.m === app.mode); setMode(L[(i + 1) % L.length].m) }; const view = computed(() => modes.find(m => m.m === app.mode)?.n ?? ''); const dm = computed(() => app.role === 'dm'); const shown = computed(() => modes.filter(m => dm.value && !app.possess ? !['fps', 'tps'].includes(m.m) : m.m !== 'fly')); const flat = computed(() => app.mode === 'iso' || app.mode === 'top'); const lname = (l: number) => l === 0 ? 'Ground' : l > 0 ? `Floor ${l}` : `Depth ${-l}`
const clock = computed(() => { const G = gs.value; return G ? `Day ${G.day}, ${String(Math.floor(G.mins / 60)).padStart(2, '0')}:${String(Math.floor(G.mins % 60)).padStart(2, '0')}` : '' }); const where = computed(() => app.possess ? 'In the body of ' + (gs.value?.mons[app.possess]?.name ?? gs.value?.chars[app.possess]?.name) : [gs.value?.camp?.mod ? app.worldName : '', app.room?.name].filter(Boolean).join(', ') || clock.value); const roads = computed(() => ((gs.value?.camp as any)?.places ?? gs.value?.camp?.mod?.list ?? []) as any[])
const said = ref<{ id: string; who?: string; text: string } | null>(null); let ct: any; watch(() => app.feed.length, () => { const b = app.feed[app.feed.length - 1]; if (app.feedOpen || !b || !['read', 'npc'].includes(b.k) || b.text === '…') return; said.value = { id: b.id, who: b.who, text: b.text }; clearTimeout(ct); ct = setTimeout(() => said.value = null, 4000 + b.text.length * 45) }); watch(() => app.feedOpen, v => { if (v) said.value = null }); const stick = ref({ on: false, x: 0, y: 0, cx: 0, cy: 0 }); const touch = ref(matchMedia('(pointer:coarse)').matches), narrow = ref(innerWidth < 900); const hb = ref(0); let raf = 0; const rs = () => narrow.value = innerWidth < 900; const side = ref(false)
const fit = () => { const c = game.value?.canvas; if (!c) return; c.style.width = narrow.value ? '100%' : `calc(100% - ${(dm.value ? 410 : 372) * app.prefs.scale}px)`; game.value!.resize() }; watch([narrow, dm, () => app.prefs.scale], fit)
onMounted(() => { fit(); addEventListener('resize', rs); if (narrow.value) app.feedOpen = false; let fr = 0; const t = () => { if (narrow.value && fr++ % 15 === 0) { const H = document.querySelector<HTMLElement>('.hb')?.offsetHeight ?? 0; if (H !== hb.value) hb.value = H } const s = game.value?.input?.stick; if (s && (s.on || stick.value.on)) stick.value = { ...s }; raf = requestAnimationFrame(t) }; t() }); onBeforeUnmount(() => { cancelAnimationFrame(raf); clearTimeout(ct); if (game.value) { game.value.canvas.style.width = ''; game.value.resize() } removeEventListener('resize', rs) })
const me = computed(() => gs.value?.chars[app.seat]); const quit = async () => { if (!app.hosting) await cancelJoin(); await leave() }; const mouse = ref({ x: 0, y: 0 }); const mv = (e: PointerEvent) => { mouse.value = { x: e.clientX, y: e.clientY } }; const cross = computed(() => !flat.value && !app.editing && app.mode !== 'fly'); const rot = (d: number) => { game.value!.view.isoGoal += d * Math.PI / 2 }; const showBar = computed(() => { const G = gs.value; if (!G || app.editing) return false; return !!app.seat || !!app.possess || (!!G.combat && dm.value) }); const inFight = computed(() => !!gs.value?.combat); const acting = computed(() => (void gs.value, active()))
watch(() => app.dock, () => { if (narrow.value) side.value = true }); const tgt = computed(() => { const G = gs.value, id = app.selToken; if (!G || !id || id === app.seat) return null; const t = app.tokens.find(k => k.id === id); if (!t) return null; const m = G.mons[id], h = G.chars[id]; const M = m ? monster(m.ref) : null; const d = app.seat ? peek()?.dist(app.seat, id) : undefined; const st = t.hp <= 0 ? 'dead' : t.hp < t.max * .25 ? 'near death' : t.hp < t.max * .55 ? 'bloodied' : t.hp < t.max ? 'hurt' : 'unhurt'; return { t, m, h, what: [h ? `level ${h.level} ${h.cls}` : m?.npc ? m.npc.role : M ? `${M.name === t.name.replace(/ \d+$/, '') ? '' : M.name + ', '}${M.type}` : '', st, d !== undefined && d < 900 ? `${d} ft` : ''].filter(Boolean).join(' · ') } }); const W = () => window.innerWidth, H = () => window.innerHeight; const hand = (k: any) => { app.menu = null; k.go?.() }
</script>
<template><div class="hud" :class="{ editing: app.editing, dm, narrow }" :style="{ '--z': app.prefs.scale, '--hb': hb + 'px' }" @pointermove="mv"><div class="field3"><Tags /><div v-if="cross" class="cross" :class="{ aim: app.aim }" /></div>
  <header class="top"><button class="mu" aria-label="Menu" @click="open('menu')"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18M3 12h18M3 18h18" stroke="currentColor" stroke-width="2.4" /></svg></button><div class="nm"><b class="cut">{{ gs?.camp?.title ?? app.worldName }}</b><small class="cut">{{ where }}</small></div>
    <template v-if="!narrow"><nav class="w" aria-label="View"><button v-for="m in shown" :key="m.m" :class="{ on: app.mode === m.m }" v-tip="[m.t, m.k]" @click="setMode(m.m)">{{ m.n }}</button></nav><nav class="w"><button v-if="app.mode === 'iso'" v-tip="['Turn the view', 'Q']" @click="rot(1)">Turn</button><button :class="{ on: app.torch }" v-tip="['Torch', 'T']" @click="toggleTorch">Torch</button><template v-if="dm"><button :class="{ on: app.shared.grid }" v-tip="['Grid', 'G']" @click="setGrid">Grid</button><button :class="{ on: app.editing }" v-tip="['Build', 'B']" @click="setEditing(!app.editing)">Build</button></template></nav>
    <nav class="w"><template v-if="app.editing"><button v-tip="['Undo', 'Ctrl Z']" :disabled="!app.undoN" @click="undoEdit">Undo</button><button v-tip="['Redo', 'Ctrl Y']" :disabled="!app.redoN" @click="redoEdit">Redo</button></template><template v-else><button v-if="roads.length > 1" @click="open('travel')">Travel</button><button v-tip="['Journal', 'J']" @click="open('journal')">Journal</button><button v-if="app.hosting" @click="open('invite')">Invite<i v-if="app.players.filter(p => p.online).length">{{ app.players.filter(p => p.online).length }}</i></button><button v-tip="['Find anything', 'Ctrl K']" class="fnd" @click="open('palette')">Find</button></template></nav></template>
    <template v-else><nav class="w"><button v-if="!app.editing" @click="cycle">{{ view }}</button><button v-if="roads.length > 1 && !app.editing" @click="open('travel')">Travel</button><button v-if="dm" :class="{ on: app.editing }" @click="setEditing(!app.editing)">Build</button><button v-if="dm && !app.editing" :class="{ on: side }" @click="side = !side">Desk</button></nav></template></header>
  <div class="lf"><Party v-if="!app.editing && (app.seat || !dm)" /><Minimap v-if="dm && !narrow && !app.editing" class="mm2" /><div v-if="app.levels.max > app.levels.min && flat || app.editing" class="lv"><button aria-label="Floor up" @click="stepLevel(1)">+</button><span>{{ lname(app.level) }}</span><button aria-label="Floor down" @click="stepLevel(-1)">−</button></div></div>
  <div class="tc"><Ribbon /><div v-if="!dm && tgt" class="tg"><Portrait :hero="tgt.h" :mon="tgt.m" :model="tgt.m?.npc && !tgt.m.npc.as ? tgt.t.m : undefined" :id="tgt.t.id" :size="52" /><span><b>{{ tgt.t.name }}</b><small>{{ tgt.what }}</small></span></div></div>
  <div v-if="!app.editing" class="col" :class="{ open: side, shut: !app.feedOpen }"><Minimap v-if="!dm || narrow" class="mm" /><DmDock v-if="dm && (!narrow || side)" class="dk" /><Feed class="fd" /></div><EditBar v-if="app.editing" />
  <div class="bc"><RollCall /><SceneCard v-if="!app.editing" /><TalkCard v-if="!app.editing && !dm" /><button v-if="narrow && said && !(gs as any)?.scene" class="sd paper" @click="app.feedOpen = true"><b v-if="said.who">{{ said.who }}</b><span v-html="rich(said.text)" /></button>
    <div v-if="app.aim" class="aimb"><b>{{ app.aim.name }}</b><span>{{ app.hovTip || (app.aim.want === 'point' ? 'Choose a place' : app.aim.n > 1 ? `Choose ${app.aim.n - app.aim.ids.length} more` : 'Choose a target') }}</span><button v-if="app.seat && ['friend', 'any'].includes(app.aim.want)" class="btn sm" @click="aimToken(app.seat)">Myself</button><button class="btn sm" @click="aimAt(null)">Cancel</button></div><button v-else-if="app.near && !flat && !app.editing && !app.modal" class="btn primary act" @click="interact">{{ app.near.label }}<kbd>E</kbd></button><div v-if="app.possess && !app.editing" class="aimb"><span>You are {{ gs?.mons[app.possess]?.name ?? gs?.chars[app.possess]?.name }}</span><button class="btn sm" @click="possess('')">Leave the body</button></div><Hotbar v-if="showBar && (app.seat || app.possess || acting)" /></div>
  <div v-if="me?.dead && app.role === 'player'" class="dead"><div class="paper fallen"><h2>{{ me.name }} has fallen</h2><p>A friend with the right spell may still call you back. Until then you may watch, or come back as someone else.</p><div v-if="mine.list.some(x => !x.dead && x.id !== me!.id)" class="chips" style="margin-bottom:12px"><button v-for="h in mine.list.filter(x => !x.dead && x.id !== me!.id)" :key="h.id" class="chip" @click="newHero(h.id)">{{ h.name }}</button></div><button class="btn" @click="quit">Leave the table</button></div></div>
  <Transition name="ttl"><div v-if="app.title" :key="app.title.id" class="ttl"><span>{{ app.title.text }}</span></div></Transition>
  <div v-if="!flat && touch && !app.editing" class="stick" :class="{ ghost: !stick.on }" :style="stick.on ? { left: stick.cx + 'px', top: stick.cy + 'px' } : {}"><i :style="{ transform: `translate(${stick.x * 30}px,${stick.y * 30}px)` }" /></div><div v-if="app.measure" class="meas" :style="{ left: app.measure.x + 'px', top: app.measure.y + 'px' }">{{ app.measure.ft }} ft</div><div v-if="app.hovTip && !touch && !app.locked && app.hover" class="meas hv" :style="{ left: mouse.x + 'px', top: mouse.y + 'px' }">{{ app.hovTip }}</div><DiceRoll />
  <div v-if="app.shared.paused" class="pause">Paused</div><div v-else-if="!inFight && app.seat && me && me.hp <= 0 && !me.dead" class="pause">You are down</div>
  <div v-if="app.lost" class="veil" style="z-index:40"><section class="modal paper" style="width:420px"><div class="body"><h2>{{ /Trying/.test(app.lost) ? 'The line went quiet' : 'Away from the table' }}</h2><p style="margin-top:8px">{{ app.lost }}</p><button class="btn" @click="quit">Back to the title</button></div></section></div>
  <div v-if="app.menu" class="mw" @pointerdown.self="app.menu = null" @contextmenu.prevent><div class="ctx paper" :style="{ left: Math.max(6, Math.min(app.menu.x, W() - 246)) + 'px', ...(app.menu.y > H() * .6 ? { bottom: Math.max(6, H() - app.menu.y) + 'px' } : { top: app.menu.y + 'px' }) }"><template v-for="(k, n) in app.menu.items" :key="n"><i v-if="k.sep" class="sep" /><button v-else :disabled="k.off && !k.go" :class="{ head: k.off && !k.go, bad: k.bad }" @click="hand(k)"><span class="grow">{{ k.t }}</span><kbd v-if="k.key">{{ k.key }}</kbd></button></template></div></div>
  <Transition name="mode"><Palette v-if="app.modal === 'palette'" /></Transition><HeroSheet v-if="app.modal === 'sheet'" :id="app.modalArg && !['pack', 'spells'].includes(app.modalArg) ? app.modalArg : undefined" /><Amend v-if="app.modal === 'amend'" /><LevelUp v-if="app.modal === 'level' && me" /><Settings v-if="app.modal === 'settings'" /><Bits v-if="app.modal" /></div></template>
<style scoped>
.hud{--col:372px;--bar:50px;position:fixed;inset:0;pointer-events:none;overflow:hidden;zoom:var(--z)}.hud.dm{--col:410px}.field3{position:absolute;left:0;top:0;bottom:0;right:var(--col);overflow:hidden}.narrow .field3{right:0}
.cross{position:absolute;left:50%;top:50%;width:6px;height:6px;margin:-3px;background:#fff;outline:1px solid #000a}.cross.aim{width:24px;height:24px;margin:-12px;background:none;outline:0;border:3px solid var(--spot)}
.top{position:absolute;left:0;right:var(--col);top:0;height:calc(var(--bar) + var(--safe-t));padding:var(--safe-t) 6px 0 var(--safe-l);background:var(--navy);display:flex;align-items:stretch;pointer-events:auto;gap:14px}.mu{width:52px;display:grid;place-items:center;background:var(--spot);color:var(--on-spot);flex:none}.mu svg{width:25px;height:25px}.mu:hover{background:var(--paper);color:var(--ink)}.nm{flex:1;min-width:0;display:flex;flex-direction:column;justify-content:center;gap:1px}.nm b{font:700 22px/1 var(--serif)}.nm small{color:var(--tx2);font-size:14.5px;line-height:1.1}.w{display:flex;align-items:stretch}.w+.w{border-left:1px solid var(--line2);padding-left:8px}.w button{padding:0 9px;font-weight:500;font-size:16px;color:var(--tx2);border-bottom:4px solid transparent;border-top:4px solid transparent;white-space:nowrap}.w button:hover:not(:disabled){color:var(--tx);border-bottom-color:var(--tx2)}.w .on{color:var(--tx);border-bottom-color:var(--spot)!important}.w button:disabled{opacity:.35}.w i{font-style:normal;background:var(--spot);color:var(--on-spot);padding:0 6px;margin-left:6px;font-size:14px}
.lf{position:absolute;left:var(--safe-l);top:calc(var(--bar) + var(--safe-t));display:grid;justify-items:start}.lv{display:flex;align-items:center;background:var(--navy);pointer-events:auto;margin-top:1px;width:210px}.lv span{flex:1;text-align:center;font-size:15.5px}.lv button{width:34px;height:32px;text-align:center;font-size:21px;line-height:1;background:var(--navy2)}.lv button:hover{background:var(--spot);color:var(--on-spot)}
.tc{position:absolute;left:222px;right:calc(var(--col) + 12px);top:calc(var(--bar) + var(--safe-t));display:grid;justify-items:center;gap:6px}.dm .tc{left:12px}.tg{display:flex;background:var(--navy);pointer-events:auto}.tg span{padding:6px 16px 6px 12px}.tg b{display:block;font:700 21px/1.05 var(--serif)}.tg small{color:var(--tx2);font-size:15px}
.col{gap:0;position:absolute;right:0;top:0;bottom:0;width:var(--col);display:flex;flex-direction:column;background:var(--navy);pointer-events:auto;padding-right:var(--safe-r)}.mm{height:196px;flex:none}.mm2{width:210px;height:150px;pointer-events:auto}.dk{flex:1.7;min-height:0}.fd{flex:1;min-height:0}.dm .fd.shut{flex:none}.col.shut .dk{flex:1}
.bc{position:absolute;left:0;right:var(--col);bottom:var(--safe-b);display:grid;grid-template-columns:minmax(0,1fr);justify-items:center;gap:0}.bc>*{pointer-events:auto}.bc :deep(.rc:has(.card))~.sc,.bc :deep(.rc:has(.card))~.tk{display:none}.aimb{display:flex;align-items:center;gap:12px;padding:7px 8px 7px 18px;background:var(--spot);color:var(--on-spot)}.aimb b{font:700 21px/1 var(--serif)}.aimb .btn{background:#0002}.act{margin-bottom:12px}.sd{max-width:min(560px,94vw);max-height:30vh;overflow:hidden;padding:11px 16px;font:400 18px/1.25 var(--serif);margin-bottom:6px}.sd b{margin-right:7px}
.dead{position:absolute;inset:0;right:var(--col);display:grid;place-items:center;z-index:15}.fallen{pointer-events:auto;padding:22px 26px 24px;max-width:440px;border-top:8px solid var(--spot)}.fallen p{margin:8px 0 14px}
.ttl{position:absolute;left:0;right:var(--col);top:23%;background:var(--duo);color:var(--spot);padding:22px clamp(20px,5vw,80px) 28px}.ttl span{font:800 clamp(38px,5.4vw,82px)/.92 var(--serif)}.ttl-enter-from{clip-path:inset(0 100% 0 0)}.ttl-leave-to{clip-path:inset(0 0 0 100%)}.ttl-enter-active,.ttl-leave-active{transition:clip-path .45s;clip-path:inset(0)}
.meas{position:absolute;transform:translate(16px,-34px);background:var(--ink);color:var(--paper);font-weight:500;padding:3px 10px;z-index:30;white-space:nowrap}.hv{transform:translate(16px,14px)}.stick{position:absolute;width:104px;height:104px;margin:-52px;border-radius:50%;border:3px solid #ffffffa0;display:grid;place-items:center}.stick i{width:44px;height:44px;border-radius:50%;background:#ffffffc0}.stick.ghost{left:calc(86px + var(--safe-l));bottom:calc(200px + var(--safe-b));opacity:.3}.pause{position:absolute;left:0;right:var(--col);top:34%;text-align:center;background:var(--paper);color:var(--ink);font:800 46px/1 var(--serif);padding:14px 0 19px}
.mw{position:fixed;inset:0;z-index:45;pointer-events:auto}.ctx{position:absolute;min-width:230px;max-height:calc(100vh - 20px);overflow:auto;border-top:6px solid var(--spot);padding:4px 0 6px}.ctx button{display:flex;align-items:center;gap:10px;width:100%;padding:5px 14px;min-height:32px}.ctx button:hover:not(:disabled){background:var(--spot);color:var(--on-spot)}.ctx .head{font:700 20px/1 var(--serif);min-height:30px}.ctx .bad{color:var(--bad)}.sep{display:block;height:1px;background:var(--line2);margin:4px 14px}
