@media(max-width:899px){.hud,.hud.dm{--col:0px;--bar:46px}.top{gap:9px;padding-right:2px}.mu{width:46px}.nm b{font-size:19px}.nm small{font-size:13.5px}.w button{font-size:15.5px;padding:0 8px}.lf{right:0}.lv{width:150px}.tc{left:0;right:0;top:calc(var(--bar) + 58px + var(--safe-t))}.dm .tc{top:calc(var(--bar) + var(--safe-t))}.col{background:none;left:0;width:auto;top:auto;pointer-events:none;bottom:calc(var(--hb,96px) + var(--safe-b));max-height:min(56vh,calc(100vh - 250px));padding:0}.dm .col{bottom:0;max-height:none}.dm .col.open{height:74vh}.col>*{pointer-events:auto}.mm{position:fixed;right:0;top:calc(var(--bar) + 58px + var(--safe-t));width:96px;height:96px}.dm .mm{top:calc(var(--bar) + var(--safe-t))}  .fd{flex:none;height:44vh}.fd.shut{height:auto;align-self:flex-end;width:222px}.dm .fd{max-height:36vh}.bc{z-index:4}.dm .bc{bottom:calc(44px + var(--safe-b))}.ttl{top:18%}}
